import { Box, Button, Typography } from '@mui/material';
import { graphql, useStaticQuery, navigate } from 'gatsby';
import { GatsbyImage, getImage } from 'gatsby-plugin-image';
import React from 'react';
import { rotate } from 'components/PageComponents/Splash';

const ComingSoon = () => {
  const data = useStaticQuery(graphql`
    {
      imageSharp(fluid: { originalName: { eq: "as-logo.png" } }) {
        gatsbyImageData(
          transformOptions: {
            duotone: { highlight: "#814bff", shadow: "#814bff" }
          }
        )
      }
    }
  `);
  return (
    <Box
      sx={{
        height: '100vh',
        width: '100%',
        bgcolor: 'black',
        position: 'relative',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        color: 'white',
        gap: '2rem',
      }}
    >
      <Typography variant="h5">Coming Soon</Typography>
      <Box
        sx={{
          height: '64px',
          width: '64px',
          zIndex: 1000,
          animation: `${rotate} 10s linear infinite`,
        }}
      >
        <GatsbyImage image={getImage(data.imageSharp)} />
      </Box>
      <Button onClick={() => navigate('/')} sx={{ minWidth: '120px' }}>
        Home
      </Button>
      <Box sx={{ height: '120px' }}></Box>
    </Box>
  );
};

export default ComingSoon;
